// Nur Delegationen aus den letzten 4 Min benachrichtigen (=genau 1 Notification pro Delegation)
const all = $input.first().json;
const delegations = Array.isArray(all) ? all : all.delegations || [];
const windowMs = 4 * 60 * 1000;
const cutoff = Date.now() - windowMs;

const toNotify = delegations.filter(d =>
  d.status === 'pending' &&
  (d.contract?.riskClass === 'A' || d.contract?.riskClass === 'B') &&
  new Date(d.createdAt).getTime() > cutoff
);

if (toNotify.length === 0) return [];

return toNotify.map(d => {
  const risk = d.contract?.riskClass || '?';
  const riskEmoji = risk === 'A' ? '🟢' : risk === 'B' ? '🟡' : '🔴';
  const goal = (d.contract?.goal || 'Keine Beschreibung').slice(0, 100);
  const workItem = d.contract?.workItemId || 'N/A';
  const cost = d.contract?.estimatedCostUsd ? `💰 ~$${Number(d.contract.estimatedCostUsd).toFixed(2)}` : '';
  const briefTitle = d.briefTitle ? `\n📄 Brief: _${d.briefTitle}_` : '';

  const message = [
    `🤖 *Delegation bereit zur Freigabe*`,
    ``,
    `*${workItem}*: ${goal}`,
    `${riskEmoji} Class ${risk} ${cost}${briefTitle}`,
    ``,
    `Tippe den Link um direkt zu genehmigen oder abzulehnen:`
  ].join('\n');

  return {
    json: {
      message,
      delegationId: d.id,
      detailUrl: `http://100.94.55.15:3002/delegations/${d.id}`
    }
  };
});

